import {PARTICLES} from './mouth-dsp.mjs';
import {HARMONICS,morphModel} from './voice-dsp.mjs';
class MouthMorph extends AudioWorkletProcessor{
 constructor(options){super();const {sounds,amount}=options.processorOptions;this.sounds=sounds;this.target=amount;this.amount=amount;this.harmonic=sounds.every(s=>s.voice);this.fade=0;this.phase=0;this.port.onmessage=e=>this.target=Math.max(0,Math.min(1,e.data.amount));
 if(this.harmonic){const m=morphModel(sounds[0].voice,sounds[1].voice,amount);this.amps=Float64Array.from(m.amplitudes);this.pitch=m.pitch}else{this.sin=new Float64Array(PARTICLES);this.cos=new Float64Array(PARTICLES);this.freq=new Float64Array(PARTICLES);for(let v=0;v<PARTICLES;v++){const phase=(v*2.399963229728653)%(Math.PI*2);this.sin[v]=Math.sin(phase);this.cos[v]=Math.cos(phase);this.freq[v]=sounds[0].frequencies[v]+(sounds[1].frequencies[v]-sounds[0].frequencies[v])*amount}this.energy=.0324;this.gain=1}}
 process(inputs,outputs){const channels=outputs[0],out=channels[0];this.amount+=(this.target-this.amount)*.16;
 if(this.harmonic){const m=morphModel(this.sounds[0].voice,this.sounds[1].voice,this.amount);for(let j=0;j<out.length;j++){this.pitch+=(m.pitch-this.pitch)*.003;this.phase=(this.phase+2*Math.PI*this.pitch/sampleRate)%(2*Math.PI);let value=0;for(let h=1;h<=HARMONICS;h++){this.amps[h-1]+=(m.amplitudes[h-1]-this.amps[h-1])*.003;if(h*this.pitch<sampleRate*.46)value+=this.amps[h-1]*Math.sin(h*this.phase-Math.PI*h*(h-1)/HARMONICS)}this.fade=Math.min(1,this.fade+1/(sampleRate*.035));out[j]=Math.tanh(value)*this.fade}}
 else{out.fill(0);const a=this.sounds[0].frequencies,b=this.sounds[1].frequencies,scale=.18*Math.sqrt(2/PARTICLES);for(let v=0;v<PARTICLES;v++){this.freq[v]+=(a[v]+(b[v]-a[v])*this.amount-this.freq[v])*.2;const hz=Math.min(sampleRate*.46,this.freq[v]),angle=2*Math.PI*hz/sampleRate,dc=Math.cos(angle),ds=Math.sin(angle);let s=this.sin[v],c=this.cos[v];for(let j=0;j<out.length;j++){out[j]+=s*scale;const next=s*dc+c*ds;c=c*dc-s*ds;s=next}const norm=1/Math.hypot(s,c);this.sin[v]=s*norm;this.cos[v]=c*norm}let energy=0;for(const v of out)energy+=v*v;this.energy=.97*this.energy+.03*energy/out.length;const targetGain=Math.min(2,.18/Math.sqrt(this.energy+1e-8));for(let j=0;j<out.length;j++){this.gain+=(targetGain-this.gain)*.001;this.fade=Math.min(1,this.fade+1/(sampleRate*.035));out[j]=Math.tanh(out[j]*this.gain)*this.fade}}
 for(let c=1;c<channels.length;c++)channels[c].set(out);return true}
}registerProcessor('mouth-morph',MouthMorph);
